from thumbor.ext.filters import _round_corner

SIZE = 16
RADIUS = 6


def _white_rgba_buffer():
    return bytearray(b"\xff\xff\xff\xff" * SIZE * SIZE)


def test_transparent_round_corner_edge_keeps_source_color():
    buffer = _white_rgba_buffer()
    result = _round_corner.apply(
        1, "RGBA", RADIUS, RADIUS, 0, 0, 0, SIZE, SIZE, bytes(buffer), 1
    )
    pixels = [result[i : i + 4] for i in range(0, len(result), 4)]
    edge = [p for p in pixels if 0 < p[3] < 255]
    assert edge, "expected partly transparent edge pixels"
    for r, g, b, _ in edge:
        assert (r, g, b) == (255, 255, 255), (r, g, b)

